<script lang="ts">
	import{onMount}from'svelte';import{Download,HardDrive,Power,RefreshCw,Save,Search,Settings2,Square,Upload,Wifi,Wrench}from'@lucide/svelte';import{connectWifi,exportBmsConfigurationUrl,getGpioStatus,getMaintenanceStatus,getWifiStatus,hasBmsSession,importBmsConfiguration,listMaintenanceStrings,rebootBms,resetBmsConfiguration,saveGpioStatus,scanWifi,startIrTask,startTcTask,stopMaintenanceTask,type GpioStatus,type IrTaskStatus,type MaintenanceString,type TcTaskStatus,type WifiNetwork,type WifiStatus}from'$lib/services/bms-api';
	import Card from './MaintenanceCard.svelte';import PanelHead from './MaintenancePanelHead.svelte';import StringSelect from './MaintenanceStringSelect.svelte';import Status from './MaintenanceStatus.svelte';import Result from './MaintenanceResult.svelte';import Log from './MaintenanceLog.svelte';import GpioCard from './GpioCard.svelte';
	const tabs:[typeof tab,string][]= [['system','System'],['wifi','WiFi'],['ir','IR Test'],['tc','Calibrate TC'],['gpio','GPIO Alarm']];
	let tab=$state<'system'|'wifi'|'ir'|'tc'|'gpio'>('system'),notice=$state(''),error=$state(''),busy=$state(false);let fileInput=$state<HTMLInputElement>();let wifi=$state<WifiStatus|null>(null),networks=$state<WifiNetwork[]>([]),passwordNetwork=$state<WifiNetwork|null>(null),wifiPassword=$state('');let strings=$state<MaintenanceString[]>([]),stringIndex=$state(1),irStart=$state(1),irEnd=$state(108),ir=$state<IrTaskStatus|null>(null),tc=$state<TcTaskStatus|null>(null),tcRange=$state(5000),tcCalibration=$state(0),gpio=$state<GpioStatus|null>(null);let gpio1=$state(1),gpio2=$state(1),direction1=$state<'input'|'output'>('output'),direction2=$state<'input'|'output'>('output');
	onMount(()=>{if(!hasBmsSession())return;void load();const timer=setInterval(()=>{void statuses()},2000);return()=>clearInterval(timer)});
	$effect(()=>{tab;if(hasBmsSession())void statuses()});
	async function load(){try{[strings,wifi]=await Promise.all([listMaintenanceStrings(),getWifiStatus()]);selectString(strings[0]?.stringIndex??1);await statuses()}catch(e){error=msg(e)}}async function statuses(){if(!hasBmsSession())return;try{if(tab==='ir')ir=await getMaintenanceStatus<IrTaskStatus>();else if(tab==='tc')tc=await getMaintenanceStatus<TcTaskStatus>();else if(tab==='gpio'){gpio=await getGpioStatus();const s1=gpio.strings?.['1'],s2=gpio.strings?.['2'];if(s1){gpio1=s1.alarmValue;direction1=s1.direction}if(s2){gpio2=s2.alarmValue;direction2=s2.direction}}}catch{}}
	function selectString(index:number){stringIndex=Number(index);const s=strings.find(v=>v.stringIndex===stringIndex);if(s){irStart=s.startTaUnitId;irEnd=s.startTaUnitId+s.cellQty-1}}
	async function run(action:()=>Promise<unknown>,success:string){busy=true;error='';try{if(hasBmsSession())await action();notice=hasBmsSession()?success:'API payload is ready; authenticate to submit it.';await statuses()}catch(e){error=msg(e)}finally{busy=false}}function msg(e:unknown){return e instanceof Error?e.message:'Request failed.'}
	async function importFile(e:Event){const file=(e.currentTarget as HTMLInputElement).files?.[0];if(file)await run(()=>importBmsConfiguration(file),'Configuration imported successfully.')}
	function exportConfig(){const a=document.createElement('a');a.href=exportBmsConfigurationUrl();a.download='';a.click();notice='Export initiated.'}
	async function reset(){if(confirm('WARNING: This deletes all battery string configurations and data. Continue?'))await run(resetBmsConfiguration,'Reset successful. Reboot is required.')}
	async function reboot(){if(confirm('Are you sure you want to reboot the device?'))await run(rebootBms,'Reboot command sent.')}
	async function scan(){await run(async()=>{networks=await scanWifi()},'WiFi scan completed.')}
	async function connect(network:WifiNetwork,password?:string){await run(async()=>{await connectWifi(network.ssid,network.bssid,password);wifi=await getWifiStatus();networks=await scanWifi()},`Connected to ${network.ssid}.`);passwordNetwork=null;wifiPassword=''}
	async function startIr(action:'activate'|'scan'){if(!Number.isInteger(Number(irStart))||!Number.isInteger(Number(irEnd))||irStart<1||irEnd>247||irStart>irEnd){error='Start and End ID must be whole numbers from 1 to 247; Start must not exceed End.';return}await run(()=>startIrTask(action,stringIndex,Number(irStart),Number(irEnd)),'IR task started; polling is temporarily paused.')}
	async function stopTask(){await run(()=>stopMaintenanceTask(),'Stop requested.')}
	async function startTc(action:'read-range'|'write-range'|'read-current'|'calibrate'){const value=action==='write-range'?Number(tcRange):action==='calibrate'?Number(tcCalibration):undefined;if(value!==undefined&&!Number.isInteger(value)){error='TC value must be a whole number.';return}if(action==='write-range'&&(value!<0||value!>65535)){error='Transformer range must be between 0 and 65535.';return}if(action==='calibrate'&&(value!<-32767||value!>32767)){error='Calibration adjustment must be between -32767 and 32767.';return}await run(()=>startTcTask(action,stringIndex,value),'TC maintenance started; polling is temporarily paused.')}
	async function saveGpio(){await run(async()=>{gpio=await saveGpioStatus(Number(gpio1),Number(gpio2),direction1,direction2)},'GPIO alarm settings saved.')}
	const ids=(v?:number[])=>v?.length?v.join(', '):'—';
</script>
<input bind:this={fileInput} type="file" accept=".csv" hidden onchange={importFile}/><section class="page"><div class="head"><h2><Wrench size={23}/>Maintenance</h2><p>System maintenance actions from the BMS source.</p></div><div class="tabs">{#each tabs as item}<button class:active={tab===item[0]} onclick={()=>tab=item[0]}>{item[1]}</button>{/each}</div>{#if notice}<div class="notice">{notice}</div>{/if}{#if error}<div class="error">{error}</div>{/if}
	{#if tab==='system'}<div class="cards"><Card icon={Settings2} title="Import / Export Configuration" text="Import an existing configuration or export the current configuration for backup."><button class="primary" onclick={()=>fileInput?.click()}><Upload size={16}/>Import Config</button><button class="secondary" onclick={exportConfig}><Download size={16}/>Export Config</button></Card><Card icon={RefreshCw} title="Reset Configuration" text="Reset all settings to factory defaults, including battery string configurations and data."><button class="danger" onclick={reset}>Reset to Default</button></Card><Card icon={Power} title="Reboot Device" text="Send the system reboot command to the BMS appliance."><button class="primary" onclick={reboot}><Power size={16}/>Reboot</button></Card></div>
	{:else if tab==='wifi'}<section class="panel"><PanelHead icon={Wifi} title="WiFi Configuration" text="Scan available networks and connect the appliance."/><div class="body"><div class="toolbar"><button class="primary" disabled={busy} onclick={scan}><Search size={16}/>Scan WiFi Networks</button>{#if wifi?.connected}<span>Connected · {wifi.ip??'IP unavailable'}</span>{/if}</div><div class="table"><table><thead><tr><th>Network name</th><th>Signal</th><th>Security</th><th></th></tr></thead><tbody>{#if networks.length}{#each networks as n}<tr><td><strong>{n.ssid}</strong>{#if n.inUse}<small>Connected</small>{/if}</td><td>{n.signal}%</td><td>{n.security||'Open'}</td><td><button class="secondary" disabled={n.inUse} onclick={()=>n.known||!n.security?connect(n):passwordNetwork=n}>{n.inUse?'Connected':'Connect'}</button></td></tr>{/each}{:else}<tr><td colspan="4" class="empty">No WiFi networks found. Run a scan to search.</td></tr>{/if}</tbody></table></div></div></section>
	{:else if tab==='ir'}<section class="panel"><PanelHead icon={Search} title="IR Test Tasks" text="Activate IR modules or scan for missing TA modules."/><div class="body"><div class="form-grid"><StringSelect bind:value={stringIndex} {strings} onchange={selectString}/><label>Start ID<input type="number" min="1" max="247" bind:value={irStart}/></label><label>End ID<input type="number" min="1" max="247" bind:value={irEnd}/></label></div><Status title="IR task status" state={ir?.state??'idle'} task={ir?.type} errorText={ir?.error}/><div class="result-grid"><Result label="Activated IR" value={ids(ir?.activatedIds)}/><Result label="Not Activated IR" value={ids(ir?.notActivatedIds)}/><Result label="Active TA" value={ids(ir?.activeIds)}/><Result label="Missing TA" value={ids(ir?.missingIds)}/></div><Log value={ir?.output}/></div><footer><button class="primary" onclick={()=>startIr('activate')}>Activate IR</button><button class="secondary" onclick={()=>startIr('scan')}>Scan Missing TA</button><button class="danger" disabled={!ir?.running} onclick={stopTask}><Square size={15}/>Stop</button></footer></section>
	{:else if tab==='tc'}<section class="panel"><PanelHead icon={Settings2} title="Calibrate TC" text="Fixed TC module 206: range 400015, calibration 400016 and current 400004."/><div class="body"><div class="form-grid"><StringSelect bind:value={stringIndex} {strings} onchange={selectString}/><label>Transformer Range<input type="number" min="0" max="65535" bind:value={tcRange}/></label><label>Calibration Adjustment<input type="number" min="-32767" max="32767" bind:value={tcCalibration}/></label><label>Module ID<input value="206" disabled/></label></div><Status title="TC task status" state={tc?.state??'idle'} task={tc?.type} errorText={tc?.error}/><div class="result-grid"><Result label="Transformer Range" value={tc?.transformerRange??'—'}/><Result label="Calibration" value={tc?.calibrationSigned??'—'}/><Result label="Latest Current" value={tc?.latestCurrentAmps===null||tc?.latestCurrentAmps===undefined?'—':`${tc.latestCurrentAmps.toFixed(3)} A`}/><Result label="Current Samples" value={`${tc?.successfulCurrentSamples??0} / 20`}/></div><Log value={tc?.output}/></div><footer><button class="secondary" onclick={()=>startTc('read-range')}>Read Range</button><button class="secondary" onclick={()=>startTc('write-range')}>Write Range</button><button class="primary" onclick={()=>startTc('read-current')}>Read Current 20s</button><button class="primary" onclick={()=>startTc('calibrate')}>Calibrate TC</button><button class="danger" disabled={!tc?.running} onclick={stopTask}>Stop</button></footer></section>
	{:else}<section class="panel"><PanelHead icon={HardDrive} title="GPIO Alarm Output" text="Configure output value and direction used when each string has an alarm."/><div class="body"><code>{gpio?.scriptPath??'scripts/set_gpio_output.sh'}</code><div class="gpio-grid"><GpioCard title="String 1" hardware="IO0 / gpio33" bind:direction={direction1} bind:alarmValue={gpio1} state={gpio?.strings?.['1']}/><GpioCard title="String 2" hardware="IO1 / gpio32" bind:direction={direction2} bind:alarmValue={gpio2} state={gpio?.strings?.['2']}/></div></div><footer><button class="primary" onclick={saveGpio}><Save size={16}/>Save GPIO settings</button></footer></section>{/if}</section>
{#if passwordNetwork}<div class="backdrop" onclick={()=>passwordNetwork=null}><dialog open onclick={e=>e.stopPropagation()}><h3>Connect to {passwordNetwork.ssid}</h3><label>Password<input type="password" bind:value={wifiPassword}/></label><footer><button class="secondary" onclick={()=>passwordNetwork=null}>Cancel</button><button class="primary" onclick={()=>connect(passwordNetwork!,wifiPassword)}>Connect</button></footer></dialog></div>{/if}
<style>
	.head h2{display:flex;align-items:center;gap:9px;margin:0;color:#172b4d;font-size:24px;font-weight:500}.head p{margin:7px 0 17px;color:#718096;font-size:16px}.tabs{display:flex;gap:4px;margin-bottom:15px;overflow-x:auto;border-bottom:1px solid #e1e7f0}.tabs button{height:40px;padding:0 13px;border:0;border-bottom:2px solid transparent;white-space:nowrap;color:#66748a;background:transparent;font:inherit;cursor:pointer}.tabs button.active{border-color:#2454b6;color:#1749ad}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card,.panel{border:1px solid #e1e7f0;border-radius:11px;background:#fff}.card{padding:18px}.card>svg{color:#315db7}.card h3{margin:11px 0 6px;color:#31415c;font-size:16px;font-weight:500}.card p{min-height:54px;margin:0;color:#7d899b;font-size:13px;line-height:1.5}.card>div{display:flex;flex-wrap:wrap;gap:7px;margin-top:14px}.panel{overflow:hidden}.panel>header{display:flex;align-items:center;gap:11px;padding:16px 18px;border-bottom:1px solid #edf0f4}.panel>header>span{display:grid;width:34px;height:34px;place-items:center;border-radius:8px;color:#2855b4;background:#eaf0ff}.panel h3{margin:0;color:#31415c;font-size:16px;font-weight:500}.panel header p{margin:4px 0 0;color:#8792a4;font-size:12px}.body{padding:18px}.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:15px}.toolbar span{color:#28784e;font-size:13px}.primary,.secondary,.danger{display:inline-flex;align-items:center;justify-content:center;gap:7px;min-height:37px;padding:0 12px;border-radius:7px;font:inherit;cursor:pointer}.primary{border:0;color:#fff;background:#1749ad}.secondary{border:1px solid #d7dfeb;color:#40516f;background:#fff}.danger{border:1px solid #f1d4d1;color:#c33127;background:#fff7f6}.table{overflow-x:auto}.table table{width:100%;min-width:620px;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid #edf1f6;color:#56657c;font-size:13px;text-align:left}th{color:#7b879a;background:#f8faff;font-size:11px;font-weight:500;text-transform:uppercase}td strong,td small{display:block}td small{color:#2e8a59}.empty{height:130px;text-align:center}.form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:13px}.form-grid label,dialog label,.gpio-grid label{display:grid;gap:6px;color:#536078;font-size:13px}input,select{width:100%;height:39px;padding:0 10px;border:1px solid #d7dfeb;border-radius:7px;color:#273853;background:#fff;font:inherit}.status{display:flex;align-items:center;gap:10px;margin-top:15px;padding:12px;border-radius:8px;background:#f6f8fc}.status strong{color:#31415c;font-size:13px}.status span{color:#617089}.status em{margin-left:auto;color:#c33127;font-size:12px}.result-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:12px}.result-grid>div{padding:11px;border-radius:8px;background:#f7f9fc}.result-grid span,.result-grid strong{display:block}.result-grid span{color:#8792a4;font-size:11px}.result-grid strong{margin-top:5px;color:#31415c;font-size:13px;font-weight:500}.log{margin-top:12px}.log>strong{color:#536078;font-size:12px}.log pre{max-height:130px;margin:6px 0 0;padding:10px;overflow:auto;border-radius:7px;color:#d9e3f8;background:#17233a;font:12px/1.5 monospace}.panel>footer{display:flex;justify-content:flex-end;flex-wrap:wrap;gap:7px;padding:11px 18px;border-top:1px solid #edf0f4}.gpio-grid{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin-top:14px}.gpio-grid article{display:grid;gap:12px;padding:15px;border:1px solid #e5eaf2;border-radius:9px}.gpio-title{display:flex;justify-content:space-between}.gpio-title strong,.gpio-title span{display:block}.gpio-title span{margin-top:3px;color:#8792a4;font-size:11px}.gpio-title em{color:#28784e;font-size:12px;font-style:normal}.mini{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.mini>span{padding:7px;border-radius:6px;color:#8792a4;background:#f7f9fc;font-size:10px}.mini strong{display:block;margin-top:3px;color:#31415c}.notice,.error{margin-bottom:13px;padding:10px 12px;border-radius:8px;font-size:13px}.notice{color:#28784e;background:#f2fbf5;border:1px solid #cae7d5}.error{color:#b42318;background:#fff1f0;border:1px solid #f3cac6}.backdrop{position:fixed;inset:0;z-index:30;display:grid;place-items:center;background:rgba(24,35,58,.25)}dialog{position:relative;width:min(420px,calc(100% - 30px));margin:0;padding:18px;border:1px solid #e1e7f0;border-radius:11px;background:#fff}dialog h3{margin:0 0 15px;color:#31415c;font-weight:500}dialog footer{display:flex;justify-content:flex-end;gap:7px;margin-top:15px}button:disabled{opacity:.5}@media(max-width:1000px){.cards{grid-template-columns:1fr 1fr}.form-grid,.result-grid{grid-template-columns:1fr 1fr}}@media(max-width:650px){.cards,.gpio-grid,.form-grid,.result-grid{grid-template-columns:1fr}.toolbar{align-items:flex-start;flex-direction:column;gap:10px}}
</style>
